#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [-0.050019785000000004, -0.11895053, -0.018046555], 'basis': [[0.0, 0.6129420699263609, 0.790127849727111], [-0.9900275781739393, -0.11130821993202818, 0.08634740662352204], [0.14087368262044053, -0.7822483615131139, 0.6068295530501164]], 'axis': [0.790127849727111, 0.08634740662352204, 0.6068295530501164], 'zmin': -0.14519291041209123, 'zmax': 0.14622811297102495, 'profiles': [{'outer': [[-0.11536690592479087, 0.04506155622696082], [-0.10873708816269248, 0.042981794169095776], [-0.10495433027009252, 0.044331796954686496], [-0.10409479144328197, 0.05042450835095652], [-0.10138560470944329, 0.05208554283121105], [-0.0949574269027776, 0.04983293209128481], [-0.09123592786799872, 0.05130060804547216], [-0.09036110160664432, 0.05740453694967887], [-0.08763219246090694, 0.05903354751913378], [-0.08117776564286272, 0.05668407001347384], [-0.07752417491741043, 0.058295168614031424], [-0.07557323714137386, 0.06507864743773074], [-0.07264295311158249, 0.06631579465557186], [-0.06721410736343794, 0.06339225643306222], [-0.0637948113717062, 0.06546196833894997], [-0.06150209358724198, 0.07215357889307006], [-0.05856961893256786, 0.07338811249202032], [-0.05513994127000445, 0.07181306011311386], [-0.058505223361385895, 0.07856771236505244], [-0.05907075948405238, 0.08317582922918226], [-0.05463450508684831, 0.08562224999232615], [-0.05240361849088312, 0.08596890764489068], [-0.04910860669019857, 0.08436838293947083], [-0.04568071898628745, 0.07818056973468178], [-0.03483498883377337, 0.084732238356122], [-0.012942013751095348, 0.09638050905720469], [0.004881533708559551, 0.10540430479094712], [0.0232654722063177, 0.10748015907301174], [0.04716182322869749, 0.10400390724737628], [0.07414351677636627, 0.09211218046393259], [0.09744024792206177, 0.06837205040617528], [0.111902268769684, 0.03697136734183309], [0.11295558657887324, 0.004452709259486682], [0.104887495581452, -0.022576023686807598], [0.09273683455670707, -0.042053875042870635], [0.07841356139558779, -0.05467714690994421], [0.06086292979920952, -0.06240139554066784], [0.062137766091264965, -0.06778013923993831], [0.06050155146560591, -0.07114975751429671], [0.056116098300848974, -0.0742299120455613], [0.05202634491902129, -0.07672429788651383], [0.05362892830580988, -0.0832121451229347], [0.05315956258764773, -0.08419180457581339], [0.03217332802299897, -0.0945165702121006], [0.03110846982327176, -0.0942255366427005], [0.028018776825581116, -0.08810292217212343], [0.025433829648713827, -0.0885209187653367], [0.021999742555648207, -0.0817197775025174], [0.02115920355997981, -0.08548282057981131], [0.018408471888679823, -0.08707719755374026], [0.01197970189762246, -0.08510036140688787], [0.008069675508025164, -0.08671861060595597], [0.00709233253007396, -0.0925546103823043], [0.004341568340472965, -0.09413947444842875], [-0.001946847436326437, -0.09184363975830148], [-0.005648867704684833, -0.0939471171292815], [-0.007529224496396667, -0.10016510092437954], [-0.010452970617695626, -0.10140061800965194], [-0.015733149439595744, -0.09868909019782361], [-0.01934976072117576, -0.10092740587435155], [-0.02126732647575184, -0.1070839761749262], [-0.02420865106797201, -0.10829960478075194], [-0.02949101343195277, -0.10555696317399384], [-0.033065959564025256, -0.10790940318566036], [-0.03528820082437574, -0.1141126105774478], [-0.03822946742367804, -0.11532822468229674], [-0.04694299095495676, -0.11113104492838799], [-0.06020526003943497, -0.09979140314216264], [-0.11824832435340904, 0.015741678208376374], [-0.11985977878140108, 0.03367506782644704], [-0.11807827620071017, 0.04339365152156272]], 'holes': [[[0.02485409144042943, 0.01176587887897407], [0.029709026695451515, -0.007655781495797348], [0.030670887703698056, -0.010073944879082442], [0.031053854771477325, -0.007708387690963228], [0.029944052810234986, -3.166526745064205e-05], [0.026714045044330986, 0.009221657744324948], [0.02441397863683533, 0.013800250733131047]]]}], 'simplify_tolerance': 4.6563073072054864e-05, 'sketch_entity_count': 93}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
